	private static final class InstrumentedQueryEvaluationContext implements QueryEvaluationContext {

		private final AtomicInteger bindingChecks = new AtomicInteger();
		private final AtomicInteger bindingSetCopies = new AtomicInteger();

		@Override
		public Predicate<BindingSet> hasBinding(String variableName) {
			return bindings -> {
				bindingChecks.incrementAndGet();
				return bindings.hasBinding(variableName);
			};
		}

		@Override
		public MutableBindingSet createBindingSet() {
			return new InstrumentedBindingSet();
		}

		@Override
		public MutableBindingSet createBindingSet(BindingSet bindings) {
			bindingSetCopies.incrementAndGet();
			MutableBindingSet copy = createBindingSet();
			bindings.forEach(binding -> copy.addBinding(binding.getName(), binding.getValue()));
			return copy;
		}

		@Override
		public Dataset getDataset() {
			return null;
		}

		@Override
		public org.eclipse.rdf4j.model.Literal getNow() {
			return null;
		}
	}

	private static final class InstrumentedBindingSet
			extends org.eclipse.rdf4j.query.algebra.evaluation.QueryBindingSet {

		private boolean isEmptyInvoked = false;

		private InstrumentedBindingSet() {
		}

		@Override
		public boolean isEmpty() {
			isEmptyInvoked = true;
			return super.isEmpty();
		}

		private boolean wasIsEmptyInvoked() {
			return isEmptyInvoked;
		}
	}

	private static final class SingleStatementTripleSource implements TripleSource {

		private final ValueFactory valueFactory = SimpleValueFactory.getInstance();
		private final Statement statement = valueFactory.createStatement(
				valueFactory.createIRI("urn:subj"),
				valueFactory.createIRI("urn:pred"),
				valueFactory.createLiteral("obj"));

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return new CloseableIteratorIteration<>(List.of(statement).iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return valueFactory;
		}
	}

	private static final class CountingFullyBoundTripleSource implements TripleSource {

		private final ValueFactory valueFactory = SimpleValueFactory.getInstance();
		private final AtomicInteger lookupCount = new AtomicInteger();
		private final Statement statement = valueFactory.createStatement(
				valueFactory.createIRI("urn:subj"),
				valueFactory.createIRI("urn:pred"),
				valueFactory.createLiteral("obj"));

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			lookupCount.incrementAndGet();
			if (statement.getSubject().equals(subj)
					&& statement.getPredicate().equals(pred)
					&& statement.getObject().equals(obj)) {
				return new CloseableIteratorIteration<>(List.of(statement).iterator());
			}
			return new CloseableIteratorIteration<>(List.<Statement>of().iterator());
		}

		@Override
		public ValueFactory getValueFactory() {
			return valueFactory;
		}
	}

	private static final class MetricCountingStatementPattern extends StatementPattern {

		private final AtomicInteger metricReads = new AtomicInteger();

		private MetricCountingStatementPattern(Var subjectVar, Var predicateVar, Var objectVar) {
			super(subjectVar, predicateVar, objectVar);
		}

		@Override
		public long getLongMetricActual(String metricName) {
			metricReads.incrementAndGet();
			return super.getLongMetricActual(metricName);
		}
	}

	private static final class UnionIndexReportingTripleSource implements TripleSource {

		private final ValueFactory valueFactory = SimpleValueFactory.getInstance();
		private final Statement firstStatement = valueFactory.createStatement(
				valueFactory.createIRI("urn:first-subj"),
				valueFactory.createIRI("urn:pred"),
				valueFactory.createLiteral("first-obj"));
		private final Statement secondStatement = valueFactory.createStatement(
				valueFactory.createIRI("urn:second-subj"),
				valueFactory.createIRI("urn:pred"),
				valueFactory.createLiteral("second-obj"));

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return new UnionIteration<>(
					new TestIndexReportingStatementIteration(List.of(firstStatement), "spoc", 6, 4, 2),
					new TestIndexReportingStatementIteration(List.of(secondStatement), "spoc", 4, 3, 1));
		}

		@Override
		public ValueFactory getValueFactory() {
			return valueFactory;
		}
	}

	private static final class FilterIndexReportingTripleSource implements TripleSource {

		private final ValueFactory valueFactory = SimpleValueFactory.getInstance();
		private final IRI acceptedValue = valueFactory.createIRI("urn:subject-object-equal");
		private final Statement acceptedStatement = valueFactory.createStatement(
				acceptedValue,
				valueFactory.createIRI("urn:pred"),
				acceptedValue);
		private final Statement rejectedStatement = valueFactory.createStatement(
				valueFactory.createIRI("urn:rejected-subj"),
				valueFactory.createIRI("urn:pred"),
				valueFactory.createIRI("urn:rejected-obj"));

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return new TestIndexReportingStatementIteration(
					List.of(acceptedStatement, rejectedStatement),
					"spoc", 2, 2, 0);
		}

		@Override
		public ValueFactory getValueFactory() {
			return valueFactory;
		}
	}

